from fractions import Fraction as F
import json
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
L={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
cost=dict(zip('TUVW',map(F,['1.8','1.5','1.2','0.8'])))
def weight(s): return sum(rows[i][1] for i in s)
def stop(s):
    return min((sum(F(rows[i][1])*L[a]['ABCD'.index(rows[i][0])] for i in s)/weight(s),a) for a in L)
def best(s,available,budget):
    opts=[stop(s)]
    if budget:
        for t in available:
            v=cost[t]
            for b in (0,1):
                sub=[i for i in s if rows[i][2]['TUVW'.index(t)]==b]
                if sub: v+=F(weight(sub),weight(s))*best(sub,available-{t},budget-1)[0]
            opts.append((v,t))
    return min(opts)
s=list(range(8)); losses={'STOP':float(stop(s)[0])}
for t in 'TUVW':
    v=cost[t]
    for b in (0,1):
        sub=[i for i in s if rows[i][2]['TUVW'.index(t)]==b]
        if sub: v+=F(weight(sub),weight(s))*best(sub,set('TUVW')-{t},1)[0]
    losses[t]=float(v)
first=best(s,set('TUVW'),2)[1]
nxt={}
if first in 'TUVW':
    for b in (0,1):
        sub=[i for i in s if rows[i][2]['TUVW'.index(first)]==b]
        nxt[str(b)]=best(sub,set('TUVW')-{first},1)[1] if sub else 'IMPOSSIBLE'
artifact={'first':first,'first_losses':losses,'next':nxt}
payload=json.dumps(artifact)
recovered=json.loads(payload)
# Independent exhaustive enumeration of every second-stage action and terminal repair.
def brute_branch(s,used):
    mass=weight(s)
    choices=[(sum(rows[i][1]*L[a]['ABCD'.index(rows[i][0])] for i in s)/mass,a) for a in L]
    for t in set('TUVW')-{used}:
        total=float(cost[t])
        for b in (0,1):
            sub=[i for i in s if rows[i][2]['TUVW'.index(t)]==b]
            if sub:
                total+=min(sum(rows[i][1]*L[a]['ABCD'.index(rows[i][0])] for i in sub) for a in L)/mass
        choices.append((total,t))
    return min(choices)
assert abs(recovered['first_losses']['STOP']-min(sum(w*L[a]['ABCD'.index(m)] for m,w,r in rows)/54 for a in L))<1e-10
for t in 'TUVW':
    value=float(cost[t])
    for b in (0,1):
        sub=[i for i in s if rows[i][2]['TUVW'.index(t)]==b]
        if sub: value+=weight(sub)/54*brute_branch(sub,t)[0]
    assert abs(recovered['first_losses'][t]-value)<1e-10
assert recovered['first']==min(recovered['first_losses'],key=recovered['first_losses'].get)
for b,a in recovered['next'].items():
    sub=[i for i in s if rows[i][2]['TUVW'.index(first)]==int(b)]
    assert a==brute_branch(sub,first)[1]
print(payload)
print('Verified all fields against direct enumeration; total weight',weight(s))

