import json
from fractions import Fraction as F
rows=[('A',3,(0,0,0)),('B',5,(0,0,1)),('D',5,(0,0,1))]
loss={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
cost={'T':F('1.8'),'U':F('1.5'),'V':F('7.2')}
def repair(s):
    mass=sum(w for m,w,r in s)
    return min((sum(F(w)*loss[a]['ABCD'.index(m)] for m,w,r in s)/mass,a) for a in loss)
remaining={a:float(sum(F(w)*loss[a]['ABCD'.index(m)] for m,w,r in rows)/13) for a in loss}
for j,t in enumerate('TUV'):
    value=cost[t]
    for b in (0,1):
        sub=[row for row in rows if row[2][j]==b]
        if sub: value+=F(sum(row[1] for row in sub),13)*repair(sub)[0]
    remaining[t]=float(value)
action=min(remaining,key=remaining.get)
after={}
if action in 'TUV':
    for b in (0,1):
        sub=[r for r in rows if r[2]['TUV'.index(action)]==b]
        after[str(b)]=repair(sub)[1] if sub else 'IMPOSSIBLE'
artifact={'posterior':{a:float(F(sum(w for m,w,r in rows if m==a),13)) for a in 'ABCD'},'remaining_losses':remaining,'action':action,'repair_after':after}
payload=json.dumps(artifact)
x=json.loads(payload)
# Independent weighted-loss totals: T,U convey no information; V splits A from B,D.
expected_repairs={'A':135/13,'B':106/13,'C':198/13,'D':109/13}
expected_tests={'T':1.8+106/13,'U':1.5+106/13,'V':7.2+40/13}
assert x['posterior']=={'A':3/13,'B':5/13,'C':0.0,'D':5/13}
for a,v in (expected_repairs|expected_tests).items(): assert abs(x['remaining_losses'][a]-v)<1e-12
assert x['action']=='B' and x['repair_after']=={}
print(payload)
print('Verified posterior, all seven losses, action, and repair_after. Duplicate display is not an additional observation.')

